// Renders assets/data/stats.json, generated by tools/build_stats.py.
// Sorting compares the underlying numbers, never the rendered strings: the
// previous comparator stripped non-digits, so an en-dash in one cell made the
// PLAYOFFS column sort by 581,819,212,425. Spec §6.6.

const STATS_PATH = "assets/data/stats.json";

const COLUMNS = [
  {
    key: "name",
    label: "TEAM",
    cls: "col-team",
    value: (m) => m.name,
    text: (m) => m.name,
  },
  {
    key: "record",
    label: "RECORD",
    cls: "col-record",
    value: (m) => m.total.wins - m.total.losses,
    text: (m) => `${m.total.wins}-${m.total.losses}`,
  },
  {
    key: "pct",
    label: "PERCENTAGE",
    cls: "col-percent",
    value: (m) => m.total.pct,
    text: (m) => `${(m.total.pct * 100).toFixed(2)}%`,
  },
  {
    key: "playoffs",
    label: "PLAYOFFS",
    cls: "col-playoffs",
    value: (m) => m.playoffs.made / Math.max(m.playoffs.possible, 1),
    text: (m) =>
      `${m.playoffs.made}/${m.playoffs.possible}` +
      (m.playoffs.years.length
        ? ` - ${m.playoffs.years.map((y) => String(y).slice(2)).join(",")}`
        : ""),
  },
  {
    key: "ring",
    label: "RING",
    cls: "col-ring",
    value: (m) => m.rings.length,
    text: (m) => {
      if (!m.rings.length) return "";
      const emoji = "💍".repeat(m.rings.length);
      const years = m.rings
        .map((r) => (r.mickeyMouse ? `${r.year}*` : String(r.year)))
        .join(", ");
      const notes = m.rings
        .map((r) => r.note)
        .filter(Boolean)
        .join("; ");
      return notes ? `${emoji}(${years}) (${notes})` : `${emoji}(${years})`;
    },
  },
  {
    key: "playoffRecord",
    label: "PLAYOFF RECORD",
    cls: "col-playoff-record",
    value: (m) => m.playoffs.record.wins - m.playoffs.record.losses,
    text: (m) => `${m.playoffs.record.wins}-${m.playoffs.record.losses}`,
  },
  {
    key: "espnW",
    label: "ESPN WINS",
    cls: "col-win-espn",
    value: (m) => m.espn.wins,
    text: (m) => String(m.espn.wins),
  },
  {
    key: "espnL",
    label: "ESPN LOSS",
    cls: "col-loss-espn",
    value: (m) => m.espn.losses,
    text: (m) => String(m.espn.losses),
  },
  {
    key: "sleeperW",
    label: "SLEEPER WINS",
    cls: "col-win-sleeper",
    value: (m) => m.sleeper.wins,
    text: (m) => String(m.sleeper.wins),
  },
  {
    key: "sleeperL",
    label: "SLEEPER LOSS",
    cls: "col-loss-sleeper",
    value: (m) => m.sleeper.losses,
    text: (m) => String(m.sleeper.losses),
  },
  {
    key: "totalW",
    label: "TOTAL WINS",
    cls: "col-total-wins",
    value: (m) => m.total.wins,
    text: (m) => String(m.total.wins),
  },
  {
    key: "totalL",
    label: "TOTAL LOSSES",
    cls: "col-total-losses",
    value: (m) => m.total.losses,
    text: (m) => String(m.total.losses),
  },
];

let MANAGERS = [];
let SORT = { key: null, direction: null };
let SEARCH_TERM = "";

function tbody() {
  return document.querySelector("#stats-table tbody");
}

function setMessage(text) {
  const body = tbody();
  if (!body) return;
  body.innerHTML = "";
  const tr = document.createElement("tr");
  const td = document.createElement("td");
  td.colSpan = COLUMNS.length;
  td.className = "stats-message";
  td.textContent = text;
  tr.appendChild(td);
  body.appendChild(tr);
}

function buildHeader() {
  const headerRow = document.getElementById("stats-header-row");
  if (!headerRow) return;
  headerRow.innerHTML = "";
  COLUMNS.forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col.label;
    th.dataset.key = col.key;
    th.classList.add("sortable");
    if (col.cls) th.classList.add(col.cls);
    if (SORT.key === col.key && SORT.direction) {
      th.classList.add(SORT.direction === "asc" ? "sort-asc" : "sort-desc");
    }
    headerRow.appendChild(th);
  });
}

function visibleRows() {
  let rows = MANAGERS.slice();

  if (SEARCH_TERM) {
    rows = rows.filter((m) =>
      COLUMNS.some((c) => c.text(m).toLowerCase().includes(SEARCH_TERM))
    );
  }

  if (SORT.key && SORT.direction) {
    const col = COLUMNS.find((c) => c.key === SORT.key);
    const sign = SORT.direction === "asc" ? 1 : -1;
    rows.sort((a, b) => {
      const va = col.value(a);
      const vb = col.value(b);
      if (typeof va === "number" && typeof vb === "number") {
        return (va - vb) * sign;
      }
      return String(va).localeCompare(String(vb)) * sign;
    });
  }

  return rows;
}

// Rendering always rebuilds from the data, so clearing a search cannot leave
// the table in a stale order under a header still showing a sort arrow.
function render() {
  const body = tbody();
  const countLabel = document.getElementById("stats-count-label");
  if (!body) return;

  buildHeader();
  const rows = visibleRows();
  body.innerHTML = "";

  rows.forEach((m) => {
    const tr = document.createElement("tr");
    COLUMNS.forEach((col) => {
      const td = document.createElement("td");
      td.textContent = col.text(m);
      if (col.cls) td.classList.add(col.cls);
      if (col.key === "pct" && m.total.pct > 0.5) td.classList.add("pct-good");
      tr.appendChild(td);
    });
    body.appendChild(tr);
  });

  if (countLabel) countLabel.textContent = String(rows.length);
}

function setupSorting() {
  const headerRow = document.getElementById("stats-header-row");
  if (!headerRow) return;
  headerRow.addEventListener("click", (evt) => {
    const th = evt.target.closest("th.sortable");
    if (!th) return;
    const key = th.dataset.key;
    if (SORT.key !== key) {
      SORT = { key, direction: "asc" };
    } else if (SORT.direction === "asc") {
      SORT = { key, direction: "desc" };
    } else {
      SORT = { key: null, direction: null };
    }
    render();
  });
}

function setupSearch() {
  const input = document.getElementById("stats-search-input");
  if (!input) return;
  input.addEventListener("input", () => {
    SEARCH_TERM = input.value.trim().toLowerCase();
    render();
  });
}

async function initStats() {
  buildHeader();
  try {
    const resp = await fetch(STATS_PATH);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const doc = await resp.json();
    MANAGERS = doc.managers;
    setupSorting();
    setupSearch();
    render();
  } catch (err) {
    // Never leave a blank table with no explanation.
    setMessage(`Couldn't load the stats (${err.message}).`);
  }
}

document.addEventListener("DOMContentLoaded", initStats);
